(()=>{
 'use strict';
 const app=document.querySelector('#app'),toast=document.querySelector('#toast');let admin=null,csrf='',page='dashboard',status='pending',query='',pageNo=1,ordersTotal=0,pollTimer=null,lastPending=null;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v)||0);
 const date=v=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(+d)?esc(v):new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium',timeStyle:'short'}).format(d)};
 const shortDate=v=>{if(!v)return'—';const d=new Date(`${v}T12:00:00`);return Number.isNaN(+d)?esc(v):new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium'}).format(d)};
 const statusInfo=s=>({pending_review_demo:['Chờ duyệt','pending'],pending_payment:['Chờ thanh toán','pending'],confirmed:['Đã xác nhận','confirmed'],confirmed_demo:['Đã xác nhận','confirmed'],rejected:['Đã từ chối','rejected'],cancelled_demo:['Đã hủy','rejected']})[s]||[s||'—','inactive'];
 const showToast=(message,error=false)=>{toast.textContent=message;toast.className=`toast show${error?' error':''}`;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.className='toast',3200)};
 async function api(path,options={}){const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};if(options.method&&options.method!=='GET'&&csrf)headers['X-CSRF-Token']=csrf;const response=await fetch(path,{credentials:'same-origin',...options,headers});let data={};try{data=await response.json()}catch{}if(response.status===401&&page!=='login'){admin=null;renderLogin();throw Error(data.error||'Phiên đăng nhập đã hết hạn.')}if(!response.ok)throw Error(data.error||data.detail||'Không thể xử lý yêu cầu.');return data;}
 const post=(url,data,method='POST')=>api(url,{method,body:JSON.stringify(data)});
 async function init(){try{const s=await api('/api/admin/session');admin=s.admin;csrf=s.csrf;render();}catch{renderLogin();}}
 function renderLogin(message=''){
  clearInterval(pollTimer);page='login';app.innerHTML=`<div class="login-screen"><section class="login-art"><div class="brand"><span class="brand-mark">T</span><span class="brand-copy">THÁI NGUYÊN TRAVEL</span></div><div class="art-copy"><div class="eyebrow">Cổng điều hành</div><h1>Chăm chút từng chuyến đi.</h1><p>Quản lý yêu cầu đặt tour, hỗ trợ khách hàng và giữ mọi thông tin vận hành trong một nơi.</p></div><div class="art-foot">Không gian dành riêng cho đội ngũ quản trị viên</div></section><section class="login-form-wrap"><form class="login-card" id="login-form"><div class="eyebrow" style="color:#788b6d">Đăng nhập an toàn</div><h2>Chào mừng trở lại</h2><p>Đăng nhập để xem và xử lý các yêu cầu đặt tour của khách hàng.</p><div class="field"><label for="username">Tên đăng nhập</label><input id="username" name="username" autocomplete="username" required autofocus></div><div class="field"><label for="password">Mật khẩu</label><input id="password" name="password" type="password" autocomplete="current-password" required></div>${message?`<div class="inline-error">${esc(message)}</div>`:''}<button class="primary full" type="submit">Đăng nhập <span aria-hidden="true">→</span></button><p class="field-help" style="margin-top:17px">Nếu bạn chưa có tài khoản, vui lòng liên hệ quản trị viên chính.</p></form></section></div>`;
  document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;try{const data=await post('/api/admin/login',{username:form.username.value,password:form.password.value});admin=data.admin;const s=await api('/api/admin/session');csrf=s.csrf;page='dashboard';render();}catch(error){renderLogin(error.message)}finally{button.disabled=false;}};
 }
 const navItems=[['dashboard','◫','Tổng quan'],['orders','▤','Đơn đặt tour'],['users','♙','Tài khoản quản trị'],['audit','◷','Nhật ký hoạt động'],['settings','⚙','Bảo mật tài khoản']];
 function layout(){return `<div class="app-layout"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">T</span><span class="brand-copy">THÁI NGUYÊN<br>TRAVEL</span></div><div class="nav-caption">Vận hành</div><nav class="nav-list">${navItems.map(([id,icon,label])=>`<button class="nav-item ${page===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span>${label}${id==='orders'?'<span class="nav-badge" id="pending-badge" hidden></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="admin-mini"><span class="avatar">${esc((admin.displayName||'A').slice(0,1).toUpperCase())}</span><span><strong>${esc(admin.displayName)}</strong><small>Quản trị viên</small></span></div><button class="quiet-btn" data-logout>↗ &nbsp; Đăng xuất</button></div></aside><section class="main-area"><header class="topbar"><button class="mobile-menu" id="mobile-menu" aria-label="Mở điều hướng">☰</button><div class="topbar-title">${navItems.find(x=>x[0]===page)?.[2]||'Quản trị'}</div><div class="top-actions"><button class="secondary" data-nav="orders">+ &nbsp; Xem yêu cầu đặt tour</button></div></header><main class="content" id="content"><section class="loading"><span class="spinner"></span><span>Đang tải…</span></section></main></section></div><div id="modal-root"></div>`;}
 function render(){if(!admin)return renderLogin();app.innerHTML=layout();document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>go(el.dataset.nav));document.querySelector('[data-logout]').onclick=logout;document.querySelector('#mobile-menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');loadPage();updateBadge();clearInterval(pollTimer);pollTimer=setInterval(()=>{updateBadge();if(page==='dashboard')loadDashboard(true);},30000);}
 function go(next){page=next;document.querySelector('#sidebar')?.classList.remove('open');render();}
 async function updateBadge(){try{const d=await api('/api/admin/dashboard'),previous=lastPending;lastPending=d.pending;const badge=document.querySelector('#pending-badge');if(badge){badge.textContent=d.pending;badge.hidden=!d.pending;}if(previous!==null&&d.pending>previous&&page==='orders'&&!document.querySelector('#modal-root .modal-backdrop')){loadOrders();showToast('Có yêu cầu đặt tour mới cần xem.');}}catch{}}
 async function loadPage(){if(page==='dashboard')return loadDashboard();if(page==='orders')return loadOrders();if(page==='users')return loadUsers();if(page==='audit')return loadAudit();if(page==='settings')return loadSettings();}
 function pageHeading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
 const row=(b)=>{const [label,cls]=statusInfo(b.bookingStatus);return `<tr><td><span class="order-code">${esc(b.code)}</span><span class="subtext">${date(b.generatedAt)}</span></td><td><strong>${esc(b.lead?.fullName||'—')}</strong><span class="subtext">${esc(b.lead?.phone||'')}</span></td><td>${esc(b.tourName)}<span class="subtext">Khởi hành ${shortDate(b.departureDate)}</span></td><td>${b.seats||0} khách</td><td><span class="status ${cls}">${label}</span></td><td><button class="row-action" data-order="${esc(b.code)}">Chi tiết →</button></td></tr>`;};
 async function loadDashboard(silent=false){try{const d=await api('/api/admin/dashboard');if(!silent){document.querySelector('#content').innerHTML=`${pageHeading('Xin chào, '+esc(admin.displayName.split(' ').at(-1)),'Tổng quan các yêu cầu đặt tour và công việc cần xử lý.',`<button class="primary" data-nav="orders">Mở danh sách đơn →</button>`)}<div class="stat-grid"><article class="stat-card"><span class="stat-icon">▤</span><div class="stat-label">Tổng yêu cầu</div><div class="stat-value">${d.total}</div><div class="stat-hint">Tất cả yêu cầu đặt tour</div></article><article class="stat-card"><span class="stat-icon">◷</span><div class="stat-label">Chờ xử lý</div><div class="stat-value">${d.pending}</div><div class="stat-hint">Cần kiểm tra và phản hồi</div></article><article class="stat-card"><span class="stat-icon">✓</span><div class="stat-label">Đã xác nhận</div><div class="stat-value">${d.confirmed}</div><div class="stat-hint">Đơn đã được chấp nhận</div></article><article class="stat-card"><span class="stat-icon">↗</span><div class="stat-label">Đã từ chối</div><div class="stat-value">${d.rejected}</div><div class="stat-hint">Đã phản hồi khách hàng</div></article></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Yêu cầu mới nhất</h2><button class="text-link" data-nav="orders">Xem tất cả →</button></div><div class="table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Chuyến đi</th><th>Khách</th><th>Trạng thái</th><th></th></tr></thead><tbody>${d.recent.length?d.recent.map(row).join(''):'<tr><td colspan="6" class="empty">Chưa có yêu cầu đặt tour.</td></tr>'}</tbody></table></div></div></section><section class="panel"><div class="panel-head"><h2>Việc cần làm</h2></div><div class="quick-stat"><span>Yêu cầu đang chờ duyệt</span><b>${d.pending}</b></div><div class="quick-stat"><span>Yêu cầu mới trong danh sách</span><b>${d.recent.length}</b></div><div style="padding-top:17px"><button class="primary full" data-nav="orders">Xem yêu cầu đang chờ</button></div><p class="field-help" style="line-height:1.6;margin-top:13px">Đơn mới được cập nhật tự động trên bảng quản trị. Mở chi tiết để kiểm tra thông tin trước khi xác nhận.</p></section></div>`;bindCommon();}else{const values=document.querySelectorAll('.stat-value');if(values.length===4)[d.total,d.pending,d.confirmed,d.rejected].forEach((v,i)=>values[i].textContent=v);}}catch(e){if(!silent)showToast(e.message,true);}}
 async function loadOrders(){try{const d=await api(`/api/admin/orders?status=${encodeURIComponent(status)}&q=${encodeURIComponent(query)}&page=${pageNo}`);ordersTotal=d.total;const pages=Math.max(1,Math.ceil(d.total/d.pageSize));document.querySelector('#content').innerHTML=`${pageHeading('Đơn đặt tour','Tra cứu thông tin khách và xử lý yêu cầu xác nhận.',`<button class="secondary" id="export-csv">Tải danh sách CSV</button>`)}<section class="panel"><div class="toolbar"><input id="search-orders" placeholder="Tìm mã đơn, tên khách, số điện thoại…" value="${esc(query)}"><select id="filter-status"><option value="all" ${status==='all'?'selected':''}>Tất cả trạng thái</option><option value="pending" ${status==='pending'?'selected':''}>Chờ duyệt</option><option value="confirmed" ${status==='confirmed'?'selected':''}>Đã xác nhận</option><option value="rejected" ${status==='rejected'?'selected':''}>Đã từ chối</option><option value="cancelled_demo" ${status==='cancelled_demo'?'selected':''}>Đã hủy</option></select></div><div class="table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Mã đơn / ngày gửi</th><th>Người đại diện</th><th>Tour / ngày đi</th><th>Số khách</th><th>Trạng thái</th><th></th></tr></thead><tbody>${d.items.length?d.items.map(row).join(''):'<tr><td colspan="6" class="empty">Không tìm thấy yêu cầu phù hợp.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${d.total?`Hiển thị ${(pageNo-1)*d.pageSize+1}–${Math.min(pageNo*d.pageSize,d.total)} trong ${d.total} yêu cầu`:'Chưa có yêu cầu'}</span><div class="pagination"><button id="prev-page" ${pageNo<=1?'disabled':''}>← Trước</button><button id="next-page" ${pageNo>=pages?'disabled':''}>Tiếp →</button></div></div></div></section>`;bindCommon();document.querySelector('#filter-status').onchange=e=>{status=e.target.value;pageNo=1;loadOrders()};let timer;document.querySelector('#search-orders').oninput=e=>{query=e.target.value;pageNo=1;clearTimeout(timer);timer=setTimeout(loadOrders,250)};document.querySelector('#prev-page').onclick=()=>{pageNo--;loadOrders()};document.querySelector('#next-page').onclick=()=>{pageNo++;loadOrders()};document.querySelector('#export-csv').onclick=async()=>{try{const first=await api(`/api/admin/orders?status=${encodeURIComponent(status)}&q=${encodeURIComponent(query)}&page=1`),items=[...first.items];for(let p=2;p<=Math.ceil(first.total/first.pageSize);p++){const next=await api(`/api/admin/orders?status=${encodeURIComponent(status)}&q=${encodeURIComponent(query)}&page=${p}`);items.push(...next.items);}exportCsv(items);showToast(`Đã tải ${items.length} yêu cầu.`);}catch(e){showToast(e.message,true)}}; }catch(e){showToast(e.message,true);}}
 function bindCommon(){document.querySelectorAll('[data-nav]').forEach(x=>x.onclick=()=>go(x.dataset.nav));document.querySelectorAll('[data-order]').forEach(x=>x.onclick=()=>openOrder(x.dataset.order));}
 function exportCsv(items){const rows=[['Mã đơn','Ngày gửi','Tên người đại diện','Điện thoại','Email','Tour','Ngày khởi hành','Số khách','Trạng thái','Tổng tiền'],...items.map(x=>[x.code,x.generatedAt,x.lead?.fullName,x.lead?.phone,x.lead?.email,x.tourName,x.departureDate,x.seats,statusInfo(x.bookingStatus)[0],x.totalVND])];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`yeu-cau-dat-tour-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href);}
 async function openOrder(code){try{const {booking:b}=await api('/api/admin/orders/'+encodeURIComponent(code));const [label,cls]=statusInfo(b.bookingStatus),modal=document.querySelector('#modal-root');modal.innerHTML=`<div class="modal-backdrop" data-dismiss><article class="modal wide" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="modal-head"><div><h2 id="detail-title">Chi tiết yêu cầu</h2><span class="subtext">${esc(b.code)} · gửi lúc ${date(b.generatedAt)}</span></div><button class="modal-close" data-close aria-label="Đóng">×</button></header><div class="modal-body"><div style="display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:17px"><div><div class="eyebrow" style="color:#758b58">${esc(b.tourCode)}</div><h3 style="margin:5px 0;font:600 23px 'Playfair Display'">${esc(b.tourName)}</h3><div class="field-help">Khởi hành ${shortDate(b.departureDate)} · ${esc(b.departureTime||'')}</div></div><span class="status ${cls}">${label}</span></div><div class="detail-grid"><section class="detail-block"><h3>Người đại diện</h3><div class="detail-line"><b>Họ và tên</b>${esc(b.lead?.fullName)}</div><div class="detail-line"><b>Điện thoại</b><a href="tel:${esc(b.lead?.phone)}">${esc(b.lead?.phone)}</a></div><div class="detail-line"><b>Email</b><a href="mailto:${esc(b.lead?.email)}">${esc(b.lead?.email)}</a></div><div class="detail-line"><b>Thành phố</b>${esc(b.lead?.city||'—')}</div>${b.specialRequests?`<div class="detail-line"><b>Ghi chú của khách</b>${esc(b.specialRequests)}</div>`:''}</section><section class="detail-block"><h3>Hành trình & chi phí</h3><div class="detail-line"><b>Số khách</b>${b.passengerCounts?.adult||0} người lớn · ${b.passengerCounts?.child||0} trẻ em · ${b.passengerCounts?.infant||0} trẻ nhỏ</div><div class="detail-line"><b>Dịch vụ đã chọn</b>${esc([b.transportId,b.pickupId,b.roomId,...(b.addonIds||[])].filter(Boolean).join(' · ')||'Theo chương trình')}</div><div class="detail-line"><b>Dự tính</b><span class="price-total">${money(b.totalVND)}</span></div>${b.invoiceRequested?'<div class="detail-line"><b>Hóa đơn</b>Khách có yêu cầu xuất hóa đơn</div>':''}</section></div>${b.travellers?.length?`<section class="detail-block" style="margin-top:16px"><h3>Thông tin hành khách <span class="field-help">(khách cung cấp)</span></h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Họ và tên</th><th>Ngày sinh</th><th>Ghi chú ăn uống</th></tr></thead><tbody>${b.travellers.map(t=>`<tr><td>${esc(t.fullName||'—')}</td><td>${esc(t.birthDate||'—')}</td><td>${esc(t.dietaryNotes||'—')}</td></tr>`).join('')}</tbody></table></div></section>`:''}${b.rejectionReason?`<div class="notice-box" style="margin-top:15px">Lý do từ chối: ${esc(b.rejectionReason)}</div>`:''}<section class="detail-block" style="margin-top:16px"><h3>Lịch sử xử lý</h3><div class="history">${(b.history||[]).slice().reverse().map(h=>`<div class="history-item"><b>${esc(statusInfo(h.status)[0])}</b> · ${date(h.at)}<br>${esc(h.by||'')}</div>`).join('')||'<div class="field-help">Chưa có lịch sử.</div>'}</div></section></div><footer class="modal-foot">${['pending_review_demo','pending_payment'].includes(b.bookingStatus)?`<button class="secondary" data-decision="reject" data-code="${esc(b.code)}">Từ chối yêu cầu</button><button class="primary" data-decision="approve" data-code="${esc(b.code)}">Xác nhận đặt tour</button>`:'<button class="secondary" data-close>Đóng</button>'}</footer></article></div>`;modal.querySelector('[data-dismiss]').onclick=e=>{if(e.target===e.currentTarget)modal.innerHTML=''};modal.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>modal.innerHTML='');modal.querySelectorAll('[data-decision]').forEach(x=>x.onclick=()=>decisionDialog(x.dataset.code,x.dataset.decision));}catch(e){showToast(e.message,true);}}
 function decisionDialog(code,decision){const approve=decision==='approve',root=document.querySelector('#modal-root');root.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-confirm-backdrop><section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2>${approve?'Xác nhận yêu cầu đặt tour':'Từ chối yêu cầu'}</h2><button class="modal-close" data-confirm-close>×</button></header><form id="decision-form"><div class="modal-body">${approve?'<div class="notice-box">Xác nhận rằng bạn đã kiểm tra lịch khởi hành, số chỗ và thông tin của khách.</div>':'<div class="field"><label for="reject-reason">Lý do từ chối <span style="color:#b8453d">*</span></label><textarea id="reject-reason" name="reason" minlength="5" maxlength="600" required placeholder="Ví dụ: Lịch khởi hành đã hết chỗ, vui lòng chọn ngày khác."></textarea><span class="field-help">Lý do sẽ được lưu trong hồ sơ để nhân viên tiện theo dõi.</span></div>'}</div><footer class="modal-foot"><button type="button" class="secondary" data-confirm-close>Quay lại</button><button class="${approve?'primary':'danger-btn'}" type="submit">${approve?'Xác nhận đơn':'Từ chối yêu cầu'}</button></footer></form></section></div>`);const overlay=root.lastElementChild;overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};overlay.querySelectorAll('[data-confirm-close]').forEach(x=>x.onclick=()=>overlay.remove());overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{await post(`/api/admin/orders/${encodeURIComponent(code)}/decision`,{decision,reason:e.currentTarget.reason?.value||''});root.innerHTML='';showToast(approve?'Đã xác nhận yêu cầu đặt tour.':'Đã từ chối yêu cầu.');loadPage();updateBadge();}catch(err){showToast(err.message,true);button.disabled=false;}};}
 async function loadUsers(){try{const {users}=await api('/api/admin/users');document.querySelector('#content').innerHTML=`${pageHeading('Tài khoản quản trị','Tạo và quản lý quyền truy cập của đội ngũ vận hành.',`<button class="primary" id="new-admin">+ &nbsp; Thêm quản trị viên</button>`)}<section class="panel"><div class="panel-head"><h2>Danh sách tài khoản</h2><span class="field-help">${users.filter(x=>x.active).length} tài khoản đang hoạt động</span></div><div class="table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Thành viên</th><th>Tên đăng nhập</th><th>Vai trò</th><th>Ngày tạo</th><th>Trạng thái</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.displayName)}</strong></td><td>${esc(u.username)}</td><td>Quản trị viên</td><td>${shortDate(u.createdAt)}</td><td><span class="status ${u.active?'active':'inactive'}">${u.active?'Đang hoạt động':'Đã khóa'}</span></td><td>${u.id===admin.id?'<span class="subtext">Tài khoản của bạn</span>':`<button class="row-action" data-toggle-user="${esc(u.id)}" data-active="${!u.active}">${u.active?'Khóa tài khoản':'Mở khóa'}</button>`}</td></tr>`).join('')}</tbody></table></div></div><div class="notice-box" style="margin-top:15px">Tài khoản quản trị có quyền xem thông tin liên hệ của khách, xử lý yêu cầu đặt tour và quản lý các tài khoản khác. Chỉ tạo tài khoản cho nhân sự được ủy quyền.</div></section>`;document.querySelector('#new-admin').onclick=createUserDialog;document.querySelectorAll('[data-toggle-user]').forEach(el=>el.onclick=async()=>{if(!confirm(el.dataset.active==='false'?'Khóa tài khoản này?':'Mở khóa tài khoản này?'))return;try{await post('/api/admin/users/'+encodeURIComponent(el.dataset.toggleUser),{active:el.dataset.active==='true'},'PATCH');showToast('Đã cập nhật trạng thái tài khoản.');loadUsers()}catch(e){showToast(e.message,true)}});}catch(e){showToast(e.message,true);}}
 function createUserDialog(){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2>Thêm quản trị viên</h2><button class="modal-close" data-close>×</button></header><form id="new-user-form"><div class="modal-body"><p class="field-help" style="font-size:12px;line-height:1.6">Tài khoản mới sẽ nhận mật khẩu tạm thời dùng một lần. Hãy chia sẻ thông tin này qua kênh nội bộ an toàn.</p><div class="field"><label>Tên hiển thị</label><input name="displayName" required minlength="2" maxlength="80" placeholder="Nguyễn Văn A"></div><div class="field"><label>Tên đăng nhập</label><input name="username" required pattern="[a-z][a-z0-9._-]{2,29}" placeholder="nguyenvana"><span class="field-help">3–30 ký tự, chữ thường, số, dấu chấm, gạch dưới hoặc gạch ngang.</span></div></div><footer class="modal-foot"><button class="secondary" type="button" data-close>Hủy</button><button class="primary" type="submit">Tạo tài khoản</button></footer></form></section></div>`;root.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>root.innerHTML='');root.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const data=await post('/api/admin/users',{displayName:e.currentTarget.displayName.value,username:e.currentTarget.username.value});root.innerHTML=`<div class="modal-backdrop"><section class="modal"><header class="modal-head"><h2>Đã tạo tài khoản</h2><button class="modal-close" data-close>×</button></header><div class="modal-body"><p>Tên đăng nhập <b>${esc(data.user.username)}</b></p><p>Mật khẩu tạm thời — hãy sao chép và gửi qua kênh an toàn:</p><div class="password-reveal" id="temp-password">${esc(data.temporaryPassword)}</div><div class="field-help" style="margin-top:13px">Mật khẩu này chỉ hiển thị lần này. Người dùng nên đổi mật khẩu sau khi đăng nhập.</div></div><footer class="modal-foot"><button class="secondary" id="copy-password">Sao chép mật khẩu</button><button class="primary" data-close>Hoàn tất</button></footer></section></div>`;root.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>root.innerHTML='');root.querySelector('#copy-password').onclick=async()=>{await navigator.clipboard.writeText(data.temporaryPassword);showToast('Đã sao chép mật khẩu tạm thời.');};loadUsers();}catch(err){showToast(err.message,true)}};}
 async function loadAudit(){try{const {items}=await api('/api/admin/audit');document.querySelector('#content').innerHTML=`${pageHeading('Nhật ký hoạt động','Theo dõi các quyết định và thay đổi trong không gian quản trị.')}<section class="panel"><div class="table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Thời gian</th><th>Quản trị viên</th><th>Hoạt động</th><th>Mã đơn / tài khoản</th><th>Ghi chú</th></tr></thead><tbody>${items.length?items.map(a=>`<tr><td>${date(a.at)}</td><td>${esc(a.username)}</td><td>${esc(({login:'Đăng nhập',approve_booking:'Xác nhận đơn',reject_booking:'Từ chối đơn',create_admin:'Tạo tài khoản',activate_admin:'Mở khóa tài khoản',deactivate_admin:'Khóa tài khoản',change_password:'Đổi mật khẩu'})[a.action]||a.action)}</td><td>${esc(a.target)}</td><td>${esc(a.details?.reason||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Chưa có hoạt động nào.</td></tr>'}</tbody></table></div></div></section>`;}catch(e){showToast(e.message,true);}}
 function loadSettings(){document.querySelector('#content').innerHTML=`${pageHeading('Bảo mật tài khoản','Giữ thông tin đăng nhập của bạn an toàn.')}<section class="panel" style="max-width:650px"><div class="panel-head"><h2>Đổi mật khẩu</h2></div><form id="password-form"><div class="field"><label>Mật khẩu hiện tại</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>Mật khẩu mới</label><input name="newPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><span class="field-help">Dùng tối thiểu 12 ký tự. Cụm từ dài dễ nhớ là một lựa chọn tốt.</span></div><div class="field"><label>Nhập lại mật khẩu mới</label><input name="confirmPassword" type="password" minlength="12" required></div><button class="primary" type="submit">Cập nhật mật khẩu</button></form></section><section class="panel" style="max-width:650px"><div class="panel-head"><h2>Phiên đăng nhập</h2></div><p class="field-help" style="font-size:12px;line-height:1.6">Phiên quản trị tự kết thúc sau 8 giờ. Luôn đăng xuất khi sử dụng máy tính chung.</p><button class="secondary" data-logout>Đăng xuất khỏi tài khoản này</button></section>`;document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(f.newPassword.value!==f.confirmPassword.value)return showToast('Hai mật khẩu mới chưa khớp.',true);try{await post('/api/admin/password',{currentPassword:f.currentPassword.value,newPassword:f.newPassword.value});f.reset();showToast('Đã cập nhật mật khẩu.');}catch(err){showToast(err.message,true)}};document.querySelector('[data-logout]').onclick=logout;}
 async function logout(){try{await post('/api/admin/logout',{});}catch{}admin=null;csrf='';renderLogin();}
 init();
})();
